_SIGNIFYD_GEO_PAY = """
Tier 1 (NYC/SF Bay Area/Seattle): $160,000 - $190,000
Tier 2 (DC Metro/Austin/Boston/Los Angeles): $150,000 - $180,000
Tier 3 (US - All Other): $140,000 - $170,000
"""


def test_parse_pay_prefers_remote_geo_band():
    from src.engine import _parse_pay, _remote_geo_pay

    assert _parse_pay(_SIGNIFYD_GEO_PAY) == (160_000, 190_000)
    assert _parse_pay(_SIGNIFYD_GEO_PAY, remote=False) == (160_000, 190_000)
    assert _parse_pay(_SIGNIFYD_GEO_PAY, remote=True) == (140_000, 170_000)
    assert _remote_geo_pay(_SIGNIFYD_GEO_PAY) == (140_000, 170_000)
    assert _parse_pay("Tier 3 (US - All Other): $140k - $170k", remote=True) == (
        140_000,
        170_000,
    )
    assert _parse_pay(
        "NYC: $160,000 - $190,000\nRemote: $140,000 - $170,000", remote=True
    ) == (140_000, 170_000)
    assert _parse_pay(
        "We're a remote company. Salary: $160,000 - $190,000", remote=True
    ) == (160_000, 190_000)
    assert _parse_pay("$80 - $100 / Hour", remote=True) == (160_000, 200_000)


def test_foreign_salary_detects_k_suffix_gbp_and_eur():
    from src.engine import _apply_listing, _foreign_salary, _parse_pay

    for blob in ("£60k", "£60K - £80K", "€85k", "GBP 60k", "EUR 85k"):
        assert _parse_pay(blob) == (None, None)
        assert _foreign_salary(f"<p>{blob} a year</p>") is True
    for blob in (
        "80,000 EUR",
        "80000 GBP",
        "80k EUR",
        "80,000 euros",
        "80k euros",
        "EUR80,000",
        "80.000 EUR",
        "80 000 EUR",
        "80 000 euros",
        "euro 80,000",
        "euros 80,000",
        "euro 80000",
        "euro 80k",
        "pounds 80,000",
        "pounds 80k",
        "80000 euros",
        "80000 euro",
        "80000 pounds",
        "80,000 yen",
        "yen 80,000",
        "80k yen",
        "80000 yen",
        "80,000 sterling",
        "80,000 quid",
        "80,000 zloty",
        "80,000 kroner",
        "80,000 kronor",
        "80,000 francs",
        "francs 80,000",
        "80k francs",
        "80000 francs",
        "80,000 dirhams",
        "80,000 rand",
        "80,000 baht",
        "80,000 shekels",
        "80,000 forint",
        "80,000 koruna",
        "80,000 rupees",
        "80,000 rupee",
    ):
        assert _parse_pay(f"{blob}. Account Executive $220,000") == (None, None)
        assert _foreign_salary(f"<p>Salary {blob} per year. Account Executive $220,000</p>") is True
    assert _parse_pay("$180,000") == (None, 180_000)
    assert _parse_pay("Experience with Euro 8. Salary $180,000") == (None, 180_000)
    assert _parse_pay("Experience with yen 8. Salary $180,000") == (None, 180_000)
    assert _parse_pay("Experience with rand 8. Salary $180,000") == (None, 180_000)
    assert _foreign_salary("<p>Salary $180,000</p>") is False
    assert _foreign_salary("<p>$60k a year</p>") is False
    assert _foreign_salary("<p>Apply now. No salary listed.</p>") is False
    euro = Opportunity(title="Engineer", url="https://jobs.example/eu")
    listed_euro = _apply_listing(
        euro, "<p>Salary euro 80,000. Account Executive $400,000</p>"
    )
    assert listed_euro is False
    assert euro.pay_high is None
    euros = Opportunity(title="Engineer", url="https://jobs.example/eu2")
    listed_euros = _apply_listing(
        euros, "<p>Salary 80000 euros. Account Executive $400,000</p>"
    )
    assert listed_euros is False
    assert euros.pay_high is None
    yen = Opportunity(title="Engineer", url="https://jobs.example/jp")
    listed_yen = _apply_listing(
        yen, "<p>Salary 80,000 yen. Account Executive $400,000</p>"
    )
    assert listed_yen is False
    assert yen.pay_high is None
    francs = Opportunity(title="Engineer", url="https://jobs.example/ch")
    listed_francs = _apply_listing(
        francs, "<p>Salary 80,000 francs. Account Executive $400,000</p>"
    )
    assert listed_francs is False
    assert francs.pay_high is None


